CREATE OR REPLACE FUNCTION public.staff_can(permission text,target_branch text DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (target_branch IS NULL OR EXISTS(SELECT 1 FROM public.branches WHERE id=target_branch AND active)) AND (public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.staff_access a JOIN public.staff_roles r ON r.id=a.role_id WHERE a.user_id=auth.uid() AND a.active AND permission=ANY(r.permissions) AND (target_branch IS NULL OR target_branch=ANY(a.branch_ids)))) $$;
DO $$ DECLARE def text; fn text; perm text; BEGIN FOR fn,perm IN SELECT * FROM (VALUES('manage_stock_category','Manage categories'),('save_customer','View customers')) x LOOP SELECT pg_get_functiondef(p.oid) INTO def FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname=fn; def:=replace(def,'NOT public.has_role(auth.uid(),''admin'')','NOT public.staff_can('||quote_literal(perm)||')'); EXECUTE def; END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.set_staff_role(uid uuid,new_role public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Manage staff access through the central staff directory'; END $$;
CREATE UNIQUE INDEX staff_role_name_case ON public.staff_roles(lower(name));